CREATE OR REPLACE FUNCTION private.apply_pass_purchase_defaults()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.purchase_price is null then
    if new.total_entries = 10 then
      new.purchase_price := 200.00;
    elsif new.total_entries = 20 then
      new.purchase_price := 320.00;
    end if;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.capture_reservation_change_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
DECLARE
  old_row jsonb := '{}'::jsonb;
  new_row jsonb := '{}'::jsonb;
  before_values jsonb := '{}'::jsonb;
  after_values jsonb := '{}'::jsonb;
  chosen_fields text[];
  different_fields text[] := '{}'::text[];
  who uuid;
  actor_kind text;
  event_kind text;
  ref_row jsonb;
  row_key text;
  record_type text;
BEGIN
  IF TG_TABLE_SCHEMA <> 'public'
     OR TG_TABLE_NAME NOT IN ('reservations','customer_booking_requests') THEN
    RAISE EXCEPTION 'Unsupported reservation audit source';
  END IF;
  IF TG_OP <> 'INSERT' THEN old_row := to_jsonb(OLD); END IF;
  IF TG_OP <> 'DELETE' THEN new_row := to_jsonb(NEW); END IF;

  record_type := CASE WHEN TG_TABLE_NAME='reservations' THEN 'reservation' ELSE 'booking_request' END;
  chosen_fields := CASE WHEN record_type='reservation'
    THEN ARRAY['dog_id','reservation_date','status','entry_type','source',
               'taxi_mode','taxi_service','taxi_amount','pass_id',
               'planned_entry_number','planned_pass_total','pass_locked','source_label']
    ELSE ARRAY['dog_id','reservation_date','status','reservation_id',
               'taxi_mode','taxi_amount','taxi_change_status',
               'requested_taxi_mode','cancellation_reason','planned_pass_request_id']
    END;
  SELECT COALESCE(jsonb_object_agg(key,value),'{}'::jsonb) INTO before_values
    FROM jsonb_each(old_row) WHERE key=ANY(chosen_fields);
  SELECT COALESCE(jsonb_object_agg(key,value),'{}'::jsonb) INTO after_values
    FROM jsonb_each(new_row) WHERE key=ANY(chosen_fields);
  IF TG_OP='UPDATE' AND before_values=after_values THEN RETURN NEW; END IF;

  SELECT COALESCE(array_agg(k ORDER BY k),'{}'::text[]) INTO different_fields
    FROM (
      SELECT key AS k FROM jsonb_object_keys(before_values || after_values) AS key
      WHERE before_values->key IS DISTINCT FROM after_values->key
    ) changes;

  event_kind := CASE
    WHEN TG_OP='INSERT' THEN 'created'
    WHEN TG_OP='DELETE' THEN 'deleted'
    WHEN new_row->>'status'='cancelled' AND old_row->>'status' IS DISTINCT FROM 'cancelled' THEN 'cancelled'
    ELSE 'updated'
  END;
  who := auth.uid();
  IF who IS NOT NULL AND EXISTS(
    SELECT 1 FROM public.staff s WHERE s.user_id=who AND s.active=true
  ) THEN actor_kind := 'admin';
  ELSIF who IS NOT NULL THEN actor_kind := 'customer';
  ELSIF current_setting('request.jwt.claim.role',true)='service_role' THEN actor_kind := 'service';
  ELSE actor_kind := 'system';
  END IF;
  ref_row := CASE WHEN TG_OP='DELETE' THEN old_row ELSE new_row END;

  INSERT INTO public.reservation_change_audit
    (entity_type,entity_id,dog_id,reservation_date,action,old_status,new_status,
     changed_fields,old_values,new_values,actor_user_id,actor_type,
     request_owner_user_id,origin,transaction_id)
  VALUES
    (record_type,(ref_row->>'id')::bigint,(ref_row->>'dog_id')::bigint,
     (ref_row->>'reservation_date')::date,event_kind,old_row->>'status',new_row->>'status',
     different_fields,before_values,after_values,who,actor_kind,
     CASE WHEN record_type='booking_request' THEN (ref_row->>'user_id')::uuid ELSE NULL END,
     CASE WHEN record_type='booking_request' THEN 'customer_booking_request'
          ELSE COALESCE(ref_row->>'source','unknown') END,
     txid_current());

  IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END
$function$

CREATE OR REPLACE FUNCTION private.clear_portal_chat(p_conversation_id bigint)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_user uuid; v_count integer;
begin
 select customer_user_id into v_user from public.portal_conversations where id=p_conversation_id for update;
 if v_user is null then return 0; end if;
 delete from public.portal_messages where conversation_id=p_conversation_id;
 get diagnostics v_count=row_count;
 delete from public.portal_notifications where entity_type='conversation' and entity_id=p_conversation_id
   and notification_type in('customer_message_admin','staff_message_customer');
 insert into public.portal_live_events(recipient_user_id,scope,entity_id) values(v_user,'all',p_conversation_id);
 return v_count;
end $function$

CREATE OR REPLACE FUNCTION private.customer_owner_link_live_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid;
begin
  if tg_op = 'DELETE' then
    v_user_id := old.user_id;
  else
    v_user_id := new.user_id;
  end if;
  if v_user_id is not null
     and exists (select 1 from auth.users where id = v_user_id) then
    insert into public.portal_live_events(recipient_user_id, scope, entity_id)
    values (v_user_id, 'all', null);
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.enqueue_google_calendar_reservation(p_reservation_id bigint, p_dog_id bigint, p_date date, p_entry_type text, p_entry_number integer, p_pass_total integer, p_pass_id bigint, p_action text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_cfg private.google_calendar_sync_config%rowtype;
  v_dog_name text;
  v_pass_total integer := p_pass_total;
  v_request_id bigint;
  v_body jsonb;
begin
  select * into v_cfg
  from private.google_calendar_sync_config
  where id = true;

  if v_cfg.id is null then
    return null;
  end if;

  select d.name into v_dog_name
  from public.dogs d
  where d.id = p_dog_id;

  if v_dog_name is null then
    return null;
  end if;

  if p_entry_type = 'pass' and v_pass_total is null and p_pass_id is not null then
    select p.total_entries into v_pass_total
    from public.passes p
    where p.id = p_pass_id;
  end if;

  v_body := jsonb_build_object(
    'secret', v_cfg.sync_secret,
    'action', p_action,
    'reservation_id', p_reservation_id::text,
    'dog_name', v_dog_name,
    'date', p_date::text,
    'entry_type', p_entry_type,
    'entry_number', p_entry_number,
    'pass_total', v_pass_total
  );

  select net.http_post(
    url := v_cfg.webhook_url,
    body := v_body,
    headers := '{"Content-Type":"application/json"}'::jsonb,
    timeout_milliseconds := 30000
  ) into v_request_id;

  return v_request_id;
end;
$function$

CREATE OR REPLACE FUNCTION private.expire_passes()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_today date := (clock_timestamp() at time zone 'Europe/Bratislava')::date;
  v_dog_id bigint;
  v_changed integer;
  v_expired integer := 0;
  v_single integer := 0;
  v_dogs integer := 0;
begin
  for v_dog_id in
    select distinct p.dog_id
    from public.passes p
    where p.status in ('active','queued')
      and p.used_entries < p.total_entries
      and p.no_expiry is not true
      and p.valid_until is not null
      and p.valid_until < v_today
    order by p.dog_id
  loop
    perform pg_catalog.pg_advisory_xact_lock(v_dog_id);

    update public.passes p
       set status = 'expired'
     where p.dog_id = v_dog_id
       and p.status in ('active','queued')
       and p.used_entries < p.total_entries
       and p.no_expiry is not true
       and p.valid_until is not null
       and p.valid_until < v_today;
    get diagnostics v_changed = row_count;
    if v_changed = 0 then continue; end if;
    v_expired := v_expired + v_changed;

    perform private.ensure_current_pass(v_dog_id);
    perform private.replan_dog_reservations(v_dog_id, v_today);

    update public.reservations r
       set entry_type = 'single',
           pass_id = null,
           planned_entry_number = null,
           planned_pass_total = null
     where r.dog_id = v_dog_id
       and r.reservation_date >= v_today
       and r.status = 'booked'
       and r.entry_type = 'pass'
       and r.pass_id is null
       and not coalesce(r.pass_locked, false);
    get diagnostics v_changed = row_count;
    v_single := v_single + v_changed;

    update public.dogs d
       set default_entry_type = 'single'
     where d.id = v_dog_id
       and d.default_entry_type = 'pass'
       and not exists (
         select 1 from public.passes p
         where p.dog_id = d.id
           and p.status = 'active'
           and p.used_entries < p.total_entries
           and (p.no_expiry is true or p.valid_until is null or p.valid_until >= v_today)
       );
    get diagnostics v_changed = row_count;
    v_dogs := v_dogs + v_changed;
  end loop;

  return jsonb_build_object('date',v_today,'expired_passes',v_expired,'single_reservations',v_single,'dogs_switched',v_dogs);
end;
$function$

CREATE OR REPLACE FUNCTION private.portal_set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  new.updated_at := now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.portal_staff_cancel_reservation_notify()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := (select auth.uid());
  v_is_staff boolean := false;
  v_dog_name text;
begin
  if old.status = 'booked' and new.status = 'cancelled' then
    select exists(select 1 from public.staff s where s.user_id=v_actor and s.active=true)
      into v_is_staff;

    if v_is_staff then
      select d.name into v_dog_name from public.dogs d where d.id=new.dog_id;

      update public.customer_booking_requests q
         set status='cancelled',
             cancellation_reason=coalesce(q.cancellation_reason,'Zrušené Chvostíkovom'),
             cancelled_at=coalesce(q.cancelled_at,now())
       where q.reservation_id=new.id and q.status='approved';

      insert into public.portal_notifications(
        recipient_user_id,notification_type,title,body,entity_type,entity_id
      )
      select distinct l.user_id,
             'booking_cancelled_by_staff',
             'Rezervácia bola zrušená',
             'Rezerváciu pre ' || coalesce(v_dog_name,'psíka') || ' na ' || to_char(new.reservation_date,'DD.MM.YYYY') || ' sme zrušili.',
             'reservation',
             new.id
        from public.dogs d
        join public.customer_owner_links l on l.owner_id=d.owner_id
        left join public.customer_profiles p on p.user_id=l.user_id
       where d.id=new.dog_id
         and coalesce(p.status,'active') <> 'suspended';
    end if;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.protect_portal_terms_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
 IF TG_TABLE_NAME='portal_terms_acceptances' THEN
  RAISE EXCEPTION 'Potvrdenia podmienok sú nemenné.';
 END IF;
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Historické podmienky nemožno zmazať.'; END IF;
 IF (NEW.id,NEW.version,NEW.title,NEW.body,NEW.document_hash,NEW.effective_from,NEW.created_at,NEW.created_by)
 IS DISTINCT FROM (OLD.id,OLD.version,OLD.title,OLD.body,OLD.document_hash,OLD.effective_from,OLD.created_at,OLD.created_by) THEN
  RAISE EXCEPTION 'Vytvorte novú verziu podmienok; historické znenie je nemenné.';
 END IF;
 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION private.recent_pass_renewal_eligible(p_dog_id bigint)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_today date := (now() at time zone 'Europe/Bratislava')::date;
  v_since date := date_trunc('week',now() at time zone 'Europe/Bratislava')::date-7;
  v_pass public.passes%rowtype;
  v_reserved integer;
begin
  if not exists(select 1 from public.dogs where id=p_dog_id and active and default_entry_type<>'free')
    or exists(select 1 from public.customer_pass_requests where dog_id=p_dog_id and status='pending')
    or exists(select 1 from public.passes where dog_id=p_dog_id and status='queued' and used_entries<total_entries)
    then return false; end if;
  select * into v_pass from public.passes where dog_id=p_dog_id and status='active'
    and used_entries<total_entries and (no_expiry or valid_until is null or valid_until>=v_today)
    order by coalesce(valid_from,purchased_on,created_at::date),id limit 1;
  if v_pass.id is not null then
    select (select count(*) from public.reservations where dog_id=p_dog_id and status='booked'
      and entry_type='pass' and reservation_date>=v_today)
      +(select count(*) from public.customer_booking_requests where dog_id=p_dog_id and status='pending'
      and reservation_date>=v_today and projected_pass_total=v_pass.total_entries and planned_pass_request_id is null)
      into v_reserved;
    return v_pass.used_entries+v_reserved>=v_pass.total_entries;
  end if;
  return exists(select 1 from public.passes p where p.dog_id=p_dog_id
    and p.status in ('active','expired','used_up')
    and (p.valid_from is null or p.valid_from<=v_today)
    and ((not coalesce(p.no_expiry,false) and p.valid_until between v_since and v_today-1)
      or (p.used_entries>=p.total_entries and exists(select 1 from public.visits v
        where v.pass_id=p.id and v.entry_type='pass' and v.pass_entry_number>=p.total_entries
        and v.visit_date between v_since and v_today))));
end $function$

CREATE OR REPLACE FUNCTION private.refresh_daily_financial_from_visit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if tg_op='DELETE' then
    perform private.refresh_daily_financial(old.visit_date);
    return old;
  elsif tg_op='UPDATE' then
    if old.visit_date is distinct from new.visit_date then
      perform private.refresh_daily_financial(old.visit_date);
    end if;
    perform private.refresh_daily_financial(new.visit_date);
    return new;
  else
    perform private.refresh_daily_financial(new.visit_date);
    return new;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION private.replan_after_pass_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if pg_trigger_depth() > 1 then return null; end if;
  perform private.ensure_current_pass(coalesce(new.dog_id,old.dog_id));
  perform private.replan_dog_reservations(coalesce(new.dog_id,old.dog_id), greatest((clock_timestamp() at time zone 'Europe/Bratislava')::date,date '2026-08-25'));
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION private.replan_after_reservation_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_today date := (clock_timestamp() at time zone 'Europe/Bratislava')::date;
begin
  if pg_trigger_depth() > 1 then return null; end if;

  if tg_op='UPDATE'
     and old.status='booked' and new.status='cancelled'
     and old.reservation_date=date '2026-08-24'
     and old.entry_type='pass'
     and old.planned_entry_number is not null then
    update public.passes p
       set used_entries = greatest(0, old.planned_entry_number - 1),
           status = case when p.status='used_up' then 'active' else p.status end
     where p.id = coalesce(old.pass_id, (
       select pp.id from public.passes pp
       where pp.dog_id=old.dog_id and pp.total_entries=old.planned_pass_total
       order by case when pp.status='active' then 0 when pp.status='used_up' then 1 else 2 end, pp.created_at desc
       limit 1
     ))
       and p.used_entries = old.planned_entry_number;
  end if;

  if tg_op='DELETE' then
    perform private.replan_dog_reservations(old.dog_id, greatest(v_today,date '2026-08-25'));
  else
    perform private.replan_dog_reservations(new.dog_id, greatest(v_today,date '2026-08-25'));
    if tg_op='UPDATE' and old.dog_id<>new.dog_id then
      perform private.replan_dog_reservations(old.dog_id, greatest(v_today,date '2026-08-25'));
    end if;
  end if;
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION private.replan_dog_reservations(p_dog_id bigint, p_from_date date DEFAULT NULL::date)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_from date := greatest(coalesce(p_from_date,(clock_timestamp() at time zone 'Europe/Bratislava')::date),date '2026-08-25');
  v_interest public.customer_pass_requests%rowtype;
  v_assign jsonb := '{}'::jsonb;
  v_virtual integer := 0;
  v_current integer;
  v_number integer;
  v_pass public.passes%rowtype;
  v_row record;
  v_type text;
  v_total integer;
  v_default_type text;
BEGIN
  PERFORM pg_catalog.pg_advisory_xact_lock(p_dog_id);
  SELECT default_entry_type INTO v_default_type FROM public.dogs WHERE id=p_dog_id;
  IF v_default_type='free' THEN
    UPDATE public.customer_booking_requests SET projected_entry_number=NULL,projected_pass_total=NULL,planned_pass_request_id=NULL
     WHERE dog_id=p_dog_id AND status='pending'
       AND (projected_entry_number IS NOT NULL OR projected_pass_total IS NOT NULL OR planned_pass_request_id IS NOT NULL);
    RETURN;
  END IF;
  PERFORM private.ensure_current_pass(p_dog_id);
  SELECT * INTO v_interest FROM public.customer_pass_requests
   WHERE dog_id=p_dog_id AND status='pending'
   ORDER BY requested_at,id LIMIT 1;
  -- Include pending requests in the same chronological ledger as booked visits.
  -- A pending interest has no pass row, price, or usage.
  FOR v_row IN
    SELECT 'reservation' AS kind,r.id,r.reservation_date,r.entry_type,
           r.pass_locked,r.pass_id,r.source_label,r.source_ref
      FROM public.reservations r
     WHERE r.dog_id=p_dog_id AND r.status='booked' AND r.reservation_date>=v_from
       AND (r.entry_type='pass'
         OR r.source_label='Čaká na kúpu permanentky'
         OR (r.source='customer_portal' AND v_interest.id IS NOT NULL AND r.entry_type='single'))
    UNION ALL
    SELECT 'request',q.id,q.reservation_date,NULL::text,false,NULL::bigint,NULL::text,NULL::text
      FROM public.customer_booking_requests q
     WHERE q.dog_id=p_dog_id AND q.status='pending' AND q.reservation_date>=v_from
    ORDER BY reservation_date,kind,id
  LOOP
    v_pass := NULL;
    v_type := null;
    IF v_row.kind='reservation' AND v_row.pass_locked AND v_row.pass_id IS NOT NULL THEN
      SELECT * INTO v_pass FROM public.passes WHERE id=v_row.pass_id AND dog_id=p_dog_id;
    ELSE
      SELECT * INTO v_pass FROM public.passes pp
       WHERE pp.dog_id=p_dog_id AND pp.status IN ('active','queued')
         AND pp.used_entries<pp.total_entries
         AND (pp.valid_from IS NULL OR pp.valid_from<=v_row.reservation_date)
         AND (coalesce(pp.no_expiry,false) OR pp.valid_until IS NULL OR pp.valid_until>=v_row.reservation_date)
         AND coalesce((v_assign->>(pp.id::text))::integer,pp.used_entries)<pp.total_entries
       ORDER BY CASE WHEN pp.status='active' THEN 0 ELSE 1 END,
                coalesce(pp.valid_from,pp.purchased_on,date '1900-01-01'),pp.created_at,pp.id
       LIMIT 1;
    END IF;
    IF v_pass.id IS NOT NULL THEN
      v_current := coalesce((v_assign->>(v_pass.id::text))::integer,v_pass.used_entries);
      v_number := CASE WHEN v_row.pass_locked AND v_row.kind='reservation'
                      THEN greatest(v_current+1,coalesce((SELECT planned_entry_number FROM public.reservations WHERE id=v_row.id),0))
                      ELSE v_current+1 END;
      IF v_number<=v_pass.total_entries THEN
        v_assign := jsonb_set(v_assign,ARRAY[v_pass.id::text],to_jsonb(v_number),true);
        v_type := 'pass';
        v_total := v_pass.total_entries;
      END IF;
    END IF;
    IF v_type IS NULL AND v_interest.id IS NOT NULL AND v_virtual<v_interest.total_entries THEN
      v_virtual := v_virtual+1;
      v_number := v_virtual;
      v_total := v_interest.total_entries;
      v_type := 'unpaid';
    END IF;
    IF v_row.kind='request' THEN
      UPDATE public.customer_booking_requests
         SET projected_entry_number=CASE WHEN v_type IS NULL THEN NULL ELSE v_number END,
             projected_pass_total=CASE WHEN v_type IS NULL THEN NULL ELSE v_total END,
             planned_pass_request_id=CASE WHEN v_type='unpaid' THEN v_interest.id ELSE NULL END
       WHERE id=v_row.id
         AND (projected_entry_number,projected_pass_total,planned_pass_request_id)
             IS DISTINCT FROM
             (CASE WHEN v_type IS NULL THEN NULL ELSE v_number END,
              CASE WHEN v_type IS NULL THEN NULL ELSE v_total END,
              CASE WHEN v_type='unpaid' THEN v_interest.id ELSE NULL END);
    ELSIF NOT v_row.pass_locked THEN
      UPDATE public.reservations
         SET entry_type=CASE WHEN v_type='pass' THEN 'pass' ELSE 'single' END,
             pass_id=CASE WHEN v_type='pass' THEN v_pass.id ELSE NULL END,
             planned_entry_number=CASE WHEN v_type IS NULL THEN NULL ELSE v_number END,
             planned_pass_total=CASE WHEN v_type IS NULL THEN NULL ELSE v_total END,
             source_label=CASE WHEN v_type='unpaid' THEN 'Čaká na kúpu permanentky'
                               WHEN source_label='Čaká na kúpu permanentky' THEN NULL ELSE source_label END
       WHERE id=v_row.id
         AND (entry_type,pass_id,planned_entry_number,planned_pass_total,source_label)
             IS DISTINCT FROM
             (CASE WHEN v_type='pass' THEN 'pass' ELSE 'single' END,
              CASE WHEN v_type='pass' THEN v_pass.id ELSE NULL END,
              CASE WHEN v_type IS NULL THEN NULL ELSE v_number END,
              CASE WHEN v_type IS NULL THEN NULL ELSE v_total END,
              CASE WHEN v_type='unpaid' THEN 'Čaká na kúpu permanentky'
                    WHEN v_row.source_label='Čaká na kúpu permanentky' THEN NULL ELSE v_row.source_label END);
    END IF;
  END LOOP;
  -- Keep already approved customer cards in step with the reservation ledger,
  -- including purchase confirmation or a handled interest without a purchase.
  UPDATE public.customer_booking_requests q
     SET projected_entry_number=r.planned_entry_number,
         projected_pass_total=r.planned_pass_total,
         planned_pass_request_id=CASE WHEN r.source_label='Čaká na kúpu permanentky'
                                      THEN v_interest.id ELSE NULL END
    FROM public.reservations r
   WHERE q.dog_id=p_dog_id AND q.status='approved' AND q.reservation_id=r.id
     AND r.reservation_date>=v_from AND r.status='booked'
     AND (q.projected_entry_number,q.projected_pass_total,q.planned_pass_request_id)
         IS DISTINCT FROM
         (r.planned_entry_number,r.planned_pass_total,
          CASE WHEN r.source_label='Čaká na kúpu permanentky' THEN v_interest.id ELSE NULL END);
END
$function$

